import sys

def solve():
    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data[0])
    p = list(map(int, data[1:n+1]))

    if n < 3:
        print("NO")
        return

    pos = [0] * (n + 1)
    for i, x in enumerate(p):
        pos[x] = i

    min_val = p[0]
    max_val = p[0]

    for i in range(1, n):
        curr = p[i]
        if min_val < curr < max_val:
            print("YES")
            return

        if curr < min_val:
            min_val = curr
        elif curr > max_val:
            max_val = curr

    print("NO")

if __name__ == "__main__":
    solve()
